create or replace TABLE KFL_PRODUCTION.DBP_DATA.COS_BONUSKAUF_1 (
	MANDANT_ID NUMBER(38,0) NOT NULL COMMENT 'Mandant_1 im DWH.',
	BONUSKAUF_ID VARCHAR(20) NOT NULL COMMENT 'Eindeutige ID einer Bonuskaufaktion, z.Bsp. 700 aus bbynr.',
	WRG_ID VARCHAR(3) NOT NULL COMMENT 'Kurzbezeichnung der Währung, z.Bsp. CZK, EUR.',
	BONUSKAUF_NAME VARCHAR(200) COMMENT 'Coupon Name.',
	BONUSKAUF_TYP VARCHAR(4) COMMENT 'Coupon Promotionsart / typ - für Reco wird immer ZAI zurückgegeben außer für RO und MD da wird es ZAIR oder ZAIM sein.',
	BONUSKAUF_KATEGORIE_BEZ VARCHAR(10) COMMENT 'Coupon Kategorie - Discount = 1 oder BonusBuy = 2.',
	GAMIFICATION_FG NUMBER(38,0) NOT NULL DEFAULT -1 COMMENT 'Flag: Ist Gamification.',
	BONUSKAUF_RABATT_WERT NUMBER(38,4) COMMENT 'Rabatt Wert.',
	BONUSKAUF_RABATT_PROZENT NUMBER(9,2) COMMENT 'Rabatt (%).',
	ANZ_PUNKTE_ZU_ZAHLEND NUMBER(38,0) COMMENT 'Punkte die für einen kaufbaren Coupon gezahlt werden müssen.',
	WG_ID NUMBER(38,0) COMMENT 'Warengruppe.',
	DAT_VON TIMESTAMP_LTZ(9) NOT NULL COMMENT 'Gültigkeitsdatum von.',
	DAT_BIS TIMESTAMP_LTZ(9) NOT NULL COMMENT 'Gültigkeitsdatum bis.',
	BONUSKAUF_BEZ VARCHAR(200) COMMENT 'Coupon Beschreibung.',
	MAX_EINLOESUNG NUMBER(38,0) COMMENT 'Max. Einlösung.',
	AKTIV_LOYALTY_GESAMT_FG NUMBER(38,0) NOT NULL DEFAULT -1 COMMENT 'Flag: Zielgruppe alle Kunden.',
	VORAKTIVIERT_FG NUMBER(38,0) NOT NULL DEFAULT -1 COMMENT 'Flag: Voraktiviert.',
	AKTIV_LOYALTY_DIGITAL_FG NUMBER(38,0) NOT NULL DEFAULT -1 COMMENT 'Flag: Zielgruppe digitale Kunden.',
	AKTIV_LOYALTY_PHYSISCH_FG NUMBER(38,0) NOT NULL DEFAULT -1 COMMENT 'Flag: Zielgruppe physische Kunden.',
	ANZ_MAX_EINKAUF NUMBER(38,0) COMMENT 'Max Anzahl für Einkauf.',
	ANZ_MIN_ARTIKEL NUMBER(38,0) COMMENT 'Min Anzahl für Artikel.',
	MIN_UMSATZ_BEDINGUNG NUMBER(38,4) COMMENT 'Coupon mit Bedingung, Mindestumsatz.',
	MIN_UMSATZ_ARTIKEL NUMBER(38,4) COMMENT 'Min Umsatz.',
	MIN_UMSATZ_BEDINGUNG_TRANSAKTION NUMBER(38,4) COMMENT 'Coupon mit Bedingung, Mindestumsatz pro Transaktion.',
	DAT_VON_BEDINGUNG TIMESTAMP_LTZ(9) COMMENT 'Startzeit der Bedingung. Für den Zeitraum in dem man die Couponbedingung erfüllen muss um den Coupon zu erhalten. Z.B. bei \"kauf drei Packungen Haribo und bekomme beim nächsten Einkauf 2€ geschenkt\" bezieht sich der Zeitraum der Bedingung auf den Kauf der 3 Packungen.',
	DAT_BIS_BEDINGUNG TIMESTAMP_LTZ(9) COMMENT 'Endzeit der Bedingung. Für den Zeitraum in dem man die Couponbedingung erfüllen muss um den Coupon zu erhalten. Z.B. bei \"kauf drei Packungen Haribo und bekomme beim nächsten Einkauf 2€ geschenkt\" bezieht sich der Zeitraum der Bedingung auf den Kauf der 3 Packungen.',
	MINDESTFREQUENZ_BEDINGUNG NUMBER(38,0) COMMENT 'Coupon mit Bedingung, Mindestfrequenz.',
	ANZ_MIN_KAUF_BBY_ARTIKEL NUMBER(38,0) COMMENT 'Menge der BonusBuy Artikel_1 die gekauft werden müssen.',
	ANZ_MIN_ZAHLEN_BBY_ARTIKEL NUMBER(38,0) COMMENT 'Menge der BonusBuy Artikel_1 die gezahlt werden müssen.',
	GRATIS_MENGE_BBY NUMBER(38,0) COMMENT 'Menge der BonusBuy Artikel_1 die es umsonst gibt.',
	ZUWEISUNG_NEUKUNDE_FG NUMBER(38,0) NOT NULL COMMENT 'Flag: Zugewiesen an Neukunden.',
	ANZ_TOP_KUNDEN NUMBER(38,0) COMMENT 'Top X Kunden.',
	ANZ_AKTUELLE_KUNDEN NUMBER(38,0) COMMENT 'Aktuelle X Kunden.',
	BONUSKAUF_DEAKTIVIEREN_FG NUMBER(38,0) NOT NULL DEFAULT -1 COMMENT 'Flag: Coupon deaktivierbar.',
	UMSATZ_AKTIVIERUNG_BRUTTO NUMBER(38,4) COMMENT 'Umsatz der generiert werden muss für die Couponaktivierung.',
	BONUSKAUF_REGEL VARCHAR(20) COMMENT 'Regel für Coupons.',
	KAUF_MIT_PUNKTE_FG NUMBER(38,0) NOT NULL DEFAULT -1 COMMENT 'Flag: Kann man den Coupon für Punkte kaufen.',
	KONDITIONSART_ID VARCHAR(4) COMMENT 'Konditionstyp.',
	BONUSKAUF_PROMOTIONSTYP VARCHAR(4) COMMENT 'Promotionstyp.',
	GESCHAEFTSVORFALL_ID VARCHAR(2) COMMENT 'Geschäftsvorfall.',
	VK_BRUTTO NUMBER(38,4) COMMENT 'Standardpreis.',
	VK_AKTION_BRUTTO_LOYALTY NUMBER(38,4) COMMENT 'Promotionspreis Loyalty.',
	BETRAG_PROMO_PROZENT NUMBER(38,4) COMMENT 'Betrag der gespart wurde.',
	VK_AKTION_BRUTTO NUMBER(38,4) COMMENT 'Promotionspreis.',
	BONUSKAUF_PARTNER_FG NUMBER(38,0) NOT NULL DEFAULT -1 COMMENT 'Flag: Partner-Coupon - Zeigt an ob es ein Partner-Coupon ist.',
	BONUSKAUF_SMP_FG NUMBER(38,0) NOT NULL DEFAULT -1 COMMENT 'Flag: Zeigt, ob der Coupon ein SMP (Schwarz Media Plattform) Coupon ist.',
	NUR_MARKTPLATZ_FG NUMBER(38,0) NOT NULL DEFAULT -1 COMMENT 'Flag: Zeigt, ob der Coupon ein Marktplatzcoupon ist.',
	BONUSKAUF_ANBIETER_NAME VARCHAR(256) COMMENT 'Name des Partners der den Coupon bereitstellt.',
	BONUSKAUF_CODE_GENERIERUNG_TYP_ID NUMBER(38,0) COMMENT 'Couponcode Typ (PCCodeTypeCode = 1, dann individueller Code oder PCCodeTypeCode = 2, dann generischer Code)',
	BONUSKAUF_CODE_TYP_ID NUMBER(38,0) COMMENT 'Code Typ (PCDisplayTypeCode = 1, dann QR Code; PCDisplayTypeCode = 2, dann Bar Code; PCDisplayTypeCode = 3, dann Text; PCDisplayTypeCode = 4, dann Link; PCDisplayTypeCode = 5, dann K Card)',
	SICHTBAR_IN_APP_FG NUMBER(38,0) NOT NULL DEFAULT -1 COMMENT 'Flag, dass anzeigt ob der Partnercoupon in der App sichtbar ist',
	SICHTBAR_IN_WEB_FG NUMBER(38,0) NOT NULL DEFAULT -1 COMMENT 'Flag, dass anzeigt ob der Partnercoupon im Web sichtbar ist',
	SICHTBAR_IN_SSC_FG NUMBER(38,0) NOT NULL DEFAULT -1 COMMENT 'Flag, dass anzeigt ob der Partnercoupon im Web 2.0 sichtbar ist',
	SICHTBAR_IN_MARKTPLATZ_FG NUMBER(38,0) NOT NULL DEFAULT -1 COMMENT 'Flag, dass anzeigt ob der Partnercoupon im Marktplatz sichtbar ist',
	SICHTBAR_IN_KAMPAGNE_FG NUMBER(38,0) NOT NULL DEFAULT -1 COMMENT 'Flag, dass anzeigt ob der Partnercoupon in der Kampagne_1 sichtbar ist',
	BONUSKAUF_VORTEILSREGELN_TXT VARCHAR(256) COMMENT 'Inhaltliche Beschreibung des Partnercoupons. Ist ein Freitextfeld',
	BONUSKAUF_KONDITIONEN_TXT VARCHAR(256) COMMENT 'Vorteile des Partnercoupons. Ist ein Freitextfeld.',
	DATZEIT_VON_EXTERN_EINLOESUNG TIMESTAMP_LTZ(9) COMMENT 'Start-Einlösedatum des Partnercoupons beim Partneranbieter. Für Coupons von Fremdanbietern (Partnern), welche ab diesem Zeitpunkt nur extern über sie eingelöst werden können. Kann nach dem DAT_VON liegen, da Coupons schon vorher dem Kunden angezeigt werden können.',
	DATZEIT_BIS_EXTERN_EINLOESUNG TIMESTAMP_LTZ(9) COMMENT 'End-Einlösedatum des Partnercoupons beim Partneranbieter. Für Coupons von Fremdanbietern (Partnern), welche bis zu  diesem Zeitpunkt nur extern über sie eingelöst werden können.',
	TD_UPDATE TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	TD_INSERT TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	constraint PK_COS_BONUSKAUF primary key (MANDANT_ID, BONUSKAUF_ID)
)COMMENT='Customer Coupon Assignments'
;